    37	impl WebsocketClient {
    38	    pub async fn connect(
    39	        &self,
    40	    ) -> anyhow::Result<
    41	        tokio_tungstenite::WebSocketStream<
    42	            tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>,
    43	        >,
    44	    > {
    45	        tracing::info!("connecting to twitch");
    46	        let (socket, _) =
    47	            tokio_tungstenite::connect_async_with_config(&self.connect_url, None, false)
    48	                .await
    49	                .context("Can't connect")?;
    50	        Ok(socket)
    51	    }
    52	
    53	    pub async fn run(&mut self) -> anyhow::Result<()> {
    54	        let mut socket = self
    55	            .connect()
    56	            .await
    57	            .context("when establishing connection")?;
    58	        loop {
    59	            tokio::select!(
    60	            Some(msg) = futures::StreamExt::next(&mut socket) => {
    61	                let span = tracing::info_span!("message received", raw_message = ?msg);
    62	                match msg {
    63	                    Err(tungstenite::Error::Protocol(
    64	                        tungstenite::error::ProtocolError::ResetWithoutClosingHandshake,
    65	                    )) => {
    66	                        tracing::warn!(
    67	                            "connection was sent an unexpected frame or was reset, reestablishing it"
    68	                        );
    69	                        let s = self.process_failure(span).await;
    70	                        if let Some(res) = s {
    71	                            socket = res;
    72	                        }
    73	                    }
    74	                    _ => {
    75	                        let message = msg.context("when getting message")?;
    76	                        let span = tracing::info_span!("processing message");
    77	                        self.process_message(message).instrument(span).await?
    78	                    }
    79	                };
    80	            }
    81	            _ = tokio::time::sleep(Duration::from_secs(40)) => {
    82	                let span = tracing::info_span!("keepalive");
    83	                tracing::warn!("keepalive timeout, reestablishing connection");
    84	                let s = self.process_failure(span).await;
    85	                if let Some(res) = s {
    86	                    socket = res;
    87	                }
    88	            })
    89	        }
    90	    }
