    92	    async fn process_failure(
    93	        &mut self,
    94	        span: tracing::Span,
    95	    ) -> Option<
    96	        tokio_tungstenite::WebSocketStream<
    97	            tokio_tungstenite::MaybeTlsStream<tokio::net::TcpStream>,
    98	        >,
    99	    > {
   100	        let res = self
   101	            .connect()
   102	            .instrument(span)
   103	            .await
   104	            .context("when reestablishing connection");
   105	
   106	        if let Err(e) = res {
   107	            tracing::error!("failed to reestablish connection: {e}");
   108	            tokio::time::sleep(Duration::from_secs(1)).await;
   109	            return None;
   110	        }
   111	        Some(res.unwrap())
   112	    }
