   114	    pub async fn process_message(&mut self, msg: tungstenite::Message) -> anyhow::Result<()> {
   115	        match msg {
   116	            tungstenite::Message::Text(s) => {
   117	                tracing::info!("{s}");
   118	                match Event::parse_websocket(&s)? {
   119	                    EventsubWebsocketData::Welcome {
   120	                        payload: WelcomePayload { session },
   121	                        ..
   122	                    }
   123	                    | EventsubWebsocketData::Reconnect {
   124	                        payload: ReconnectPayload { session },
   125	                        ..
   126	                    } => {
   127	                        self.process_welcome_message(session).await?;
   128	                        Ok(())
   129	                    }
   130	                    EventsubWebsocketData::Notification { metadata, payload } => {
   131	                        self.process_notification(payload, &metadata, &s)?;
   132	                        Ok(())
   133	                    }
   134	                    EventsubWebsocketData::Revocation {
   135	                        metadata: _,
   136	                        payload: _,
   137	                    } => Ok(()),
   138	                    EventsubWebsocketData::Keepalive {
   139	                        metadata: _,
   140	                        payload: _,
   141	                    } => Ok(()),
   142	                    _ => Ok(()),
   143	                }
   144	            }
   145	            tungstenite::Message::Close(_) => todo!(),
   146	            _ => Ok(()),
   147	        }
   148	    }
