   102	fn next_message(queues: &EventQueues) -> Option<DisplayMessage> {
   103	    if !types::EVENT_QUEUE_ACTIVE.load(std::sync::atomic::Ordering::SeqCst) {
   104	        return None;
   105	    }
   106	    queues
   107	        .lock()
   108	        .expect("event queue lock poisoned")
   109	        .unpublished_events
   110	        .pop_front()
   111	}
