   113	fn broadcast(connections: &ConnectionMap, message: Message) {
   114	    connections
   115	        .lock()
   116	        .expect("connection lock poisoned")
   117	        .retain(|peer, sender| {
   118	            let connected = sender.unbounded_send(message.clone()).is_ok();
   119	            if !connected {
   120	                tracing::debug!(%peer, "Removing disconnected browser");
   121	            }
   122	            connected
   123	        });
   124	}
