   126	async fn process_events(queues: &EventQueues, connections: &ConnectionMap) -> anyhow::Result<()> {
   127	    loop {
   128	        let Some(message) = next_message(queues) else {
   129	            tokio::time::sleep(std::time::Duration::from_millis(500)).await;
   130	            continue;
   131	        };
   132	        let html = html! {
   133	            div id="notifications" class="alert" hx-swap="afterend" hx-target="notifications" {
   134	                div class="wrapper" {
   135	                    (htmx::get_display_html(&message))
   136	                }
   137	            }
   138	        };
   139	        broadcast(connections, Message::Text(html.into()));
   140	        tokio::time::sleep(std::time::Duration::from_secs(10)).await;
   141	        let html = html! {
   142	            div id="notifications" hx-swap="delete" hx-target="notifications" {}
   143	        };
   144	        broadcast(connections, Message::Text(html.into()));
   145	        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
   146	    }
