   149	async fn accept_connections(listener: TcpListener, state: ConnectionMap) -> anyhow::Result<()> {
   150	    // Dropping the set cancels active browser connections when the server stops.
   151	    let mut connections = JoinSet::new();
   152	    loop {
   153	        tokio::select! {
   154	            connection = listener.accept() => {
   155	                let (stream, peer) = connection.context("accept browser WebSocket")?;
   156	                connections.spawn(accept_connection(peer, stream, state.clone()));
   157	            }
   158	            Some(result) = connections.join_next(), if !connections.is_empty() => {
   159	                result.context("browser connection task failed")?;
   160	            }
   161	        }
   162	    }
   163	}
   164	
   165	async fn accept_connection(peer: SocketAddr, stream: TcpStream, state: ConnectionMap) {
   166	    let result = handle_connection(peer, stream, &state).await;
   167	    state
   168	        .lock()
   169	        .expect("connection lock poisoned")
   170	        .remove(&peer);
   171	    if let Err(error) = result {
   172	        match error {
   173	            Error::ConnectionClosed | Error::Protocol(_) | Error::Utf8 => (),
   174	            error => tracing::warn!(%peer, %error, "Browser WebSocket failed"),
   175	        }
   176	    }
   177	}
   178	
   179	async fn handle_connection(
   180	    peer: SocketAddr,
   181	    stream: TcpStream,
   182	    state: &ConnectionMap,
   183	) -> Result<()> {
   184	    let socket = accept_async(stream).await?;
   185	    let (sender, mut receiver) = unbounded();
   186	    state
   187	        .lock()
   188	        .expect("connection lock poisoned")
   189	        .insert(peer, sender);
   190	    let (mut socket_sender, mut socket_receiver) = socket.split();
   191	    loop {
   192	        tokio::select! {
   193	            message = socket_receiver.next() => {
   194	                let Some(message) = message else { break };
   195	                let message = message?;
   196	                if message.is_text() || message.is_binary() {
   197	                    socket_sender.send(message).await?;
   198	                } else if message.is_close() {
   199	                    break;
   200	                }
   201	            }
   202	            message = receiver.next() => {
   203	                let Some(message) = message else { break };
   204	                socket_sender.send(message).await?;
   205	            }
   206	        }
   207	    }
   208	    Ok(())
   209	}
