     7	pub fn install_utils() -> anyhow::Result<()> {
     8	    let _ = dotenvy::dotenv(); //ignore error
     9	    install_tracing().context("install tracing")?;
    10	    Ok(())
    11	}
    12	
    13	/// Log file path: `BRUCE_LOG`, then `NULL_TWITCH_LOG`, else `bruce.log`.
    14	/// Logs go to stderr and to this file (append mode); use the file when a TUI owns the terminal.
    15	fn install_tracing() -> anyhow::Result<()> {
    16	    use tracing_error::ErrorLayer;
    17	    use tracing_subscriber::prelude::*;
    18	    use tracing_subscriber::{fmt, EnvFilter};
    19	
    20	    let log_path: PathBuf = std::env::var_os("BRUCE_LOG")
    21	        .or_else(|| std::env::var_os("NULL_TWITCH_LOG"))
    22	        .filter(|s| !s.is_empty())
    23	        .map(PathBuf::from)
    24	        .unwrap_or_else(|| PathBuf::from("bruce.log"));
    25	
    26	    if let Some(dir) = log_path.parent() {
    27	        if !dir.as_os_str().is_empty() {
    28	            std::fs::create_dir_all(dir)
    29	                .with_context(|| format!("create log dir {}", dir.display()))?;
    30	        }
    31	    }
    32	
    33	    let log_file = std::fs::OpenOptions::new()
    34	        .create(true)
    35	        .append(true)
    36	        .open(&log_path)
    37	        .with_context(|| format!("open log file {}", log_path.display()))?;
    38	
    39	    let fmt_file = fmt::layer()
    40	        .with_writer(Mutex::new(log_file))
    41	        .with_file(true)
    42	        .with_line_number(true)
    43	        .with_target(true)
    44	        .with_ansi(false);
    45	
    46	    let mut filter_layer =
    47	        EnvFilter::try_from_default_env().or_else(|_| EnvFilter::try_new("info"))?;
    48	    for directive in [
    49	        "hyper=error",
    50	        "h2=error",
    51	        "rustls=error",
    52	        "tungstenite=error",
    53	        "want=info",
    54	        "reqwest=info",
    55	        "mio=info",
    56	    ] {
    57	        filter_layer = filter_layer.add_directive(directive.parse()?);
    58	    }
    59	
    60	    filter_layer = filter_layer.add_directive(Level::DEBUG.into());
    61	
    62	    tracing_subscriber::registry()
    63	        .with(filter_layer)
    64	        .with(fmt_file)
    65	        .with(ErrorLayer::default())
    66	        .try_init()
    67	        .map_err(|error| anyhow::anyhow!("initialize tracing: {error}"))?;
    68	
    69	    tracing::info!(path = %log_path.display(), "tracing file sink enabled");
    70	    Ok(())
    71	}
