    60	/// Add `points` to a player's running total, registering them first if needed.
    61	/// The stored username is refreshed so renamed players keep their history.
    62	pub async fn add_points(
    63	    pool: &SqlitePool,
    64	    platform: MessagePlatform,
    65	    user_id: &str,
    66	    username: &str,
    67	    points: i64,
    68	) -> anyhow::Result<UserScore> {
    69	    let score = get_player_score(pool, platform, user_id, username).await?;
    70	    Ok(sqlx::query_as::<_, UserScore>(
    71	        "UPDATE wordle_highscores SET total_points = total_points + ?, username = ?
    72	         WHERE id = ? RETURNING id, total_points",
    73	    )
    74	    .bind(points)
    75	    .bind(username)
    76	    .bind(score.id)
    77	    .fetch_one(pool)
    78	    .await?)
    79	}
