519	struct GameRound<'a> {
520	    word: [u8; 5],
521	    players_votes: HashMap<Player, (Word, u32)>,
522	    spell_checker: &'a HashSet<String>,
523	    guess_position: u32,
524	}
525	
526	type Word = [u8; 5];
527	
528	struct VoteIndexer {
529	    votes: u32,
530	    position_in_round: u32,
531	}
532	
533	impl<'a> GameRound<'a> {
534	    // Creates a new game round with a predefined word
535	    // word MUST be 5 characters long
536	    pub fn new(word: Word, spell_checker: &'a HashSet<String>) -> Self {
537	        Self {
538	            word,
539	            players_votes: HashMap::new(),
540	            spell_checker,
541	            guess_position: 0,
542	        }
543	    }
544	
545	    pub fn new_guess(&mut self, player: Player, guess: String) -> bool {
546	        let upper = guess.to_uppercase();
547	        if !self.validate_guess(&upper) {
548	            return false;
549	        }
550	        self.guess_position += 1;
551	        let mut arrays_of_u8 = Word::default();
552	        arrays_of_u8.copy_from_slice(upper.as_bytes());
553	        self.players_votes
554	            .insert(player, (arrays_of_u8, self.guess_position));
555	        true
556	    }
557	
558	    // Validate guess
559	    pub fn validate_guess(&self, guess: &str) -> bool {
560	        if guess.len() != 5 {
561	            return false;
562	        }
563	
564	        if guess.contains(' ') {
565	            return false;
566	        }
567	
568	        // Check if the guess is in the spell checker
569	        if !self.spell_checker.contains(&guess.to_uppercase()) {
570	            return false;
571	        }
572	
573	        // Check if the guess is a valid word
574	        // For now, we just check if it contains only ASCII characters
575	        guess.is_ascii()
576	    }
577	
578	    pub fn build_cells(&self, guess: Word) -> RowMessage {
579	        let mut cells = [Cell::default(); 5];
580	        let mut letter_counts = HashMap::new();
581	
582	        // First pass: mark Correct and count leftover letters
583	        for i in 0..5 {
584	            if guess[i] == self.word[i] {
585	                cells[i] = (guess[i], LetterStatus::Correct).into();
586	            } else {
587	                letter_counts
588	                    .entry(self.word[i])
589	                    .and_modify(|count| *count += 1)
590	                    .or_insert(1);
591	            }
592	        }
593	
594	        // Second pass: mark Present or Absent
595	        for i in 0..5 {
596	            if cells[i].status == LetterStatus::Correct {
597	                continue;
598	            }
599	
600	            if let Some(count) = letter_counts.get_mut(&guess[i]) {
601	                if *count > 0 {
602	                    cells[i] = (guess[i], LetterStatus::Present).into();
603	                    *count -= 1;
604	                } else {
605	                    cells[i] = (guess[i], LetterStatus::Absent).into();
606	                }
607	            } else {
608	                cells[i] = (guess[i], LetterStatus::Absent).into();
609	            }
610	        }
611	
612	        RowMessage { data: cells }
613	    }
614	
615	    // Select the winning guess based on the votes
616	    pub fn select_round_winner(&self, word: Word) -> Option<Word> {
617	        // If there are multiple words with the same number of votes, first check to see if any of
618	        // them are the correct word, and pick that word.
619	        // Second if there are no correct words, pick the lowest position word with the most votes.
620	        let mut total_votes = HashMap::new();
621	        let mut highest_vote = 0;
622	
623	        // Build a map of all votes
624	        for (voted_word, pos) in self.players_votes.values() {
625	            let votes = total_votes.entry(*voted_word).or_insert(VoteIndexer {
626	                votes: 0,
627	                position_in_round: 10000,
628	            });
629	            votes.votes += 1;
630	            if pos < &votes.position_in_round {
631	                votes.position_in_round = *pos;
632	            }
633	            if votes.votes > highest_vote {
634	                highest_vote = votes.votes;
635	            }
636	        }
637	
638	        // Find the word with the most votes
639	        // If there is a tie, pick the word with the lowest position in the round
640	        let mut winning_word = ([0; 5], 1000000);
641	        for (voted_word, vote_indexer) in total_votes.iter() {
642	            if vote_indexer.votes == highest_vote {
643	                // Check if the voted word is the correct word
644	                if *voted_word == word {
645	                    return Some(*voted_word);
646	                }
647	                if winning_word.1 > vote_indexer.position_in_round {
648	                    winning_word = (*voted_word, vote_indexer.position_in_round);
649	                }
650	            }
651	        }
652	        Some(winning_word.0)
653	    }
654	
655	    /// Players whose current vote is `word`.
656	    pub fn voters_for(&self, word: Word) -> Vec<&Player> {
657	        self.players_votes
658	            .iter()
659	            .filter(|(_, (voted_word, _))| *voted_word == word)
660	            .map(|(player, _)| player)
661	            .collect()
662	    }
663	
664	    pub fn reset_votes(&mut self) {
665	        self.players_votes.clear();
666	    }
667	}
